/**
 * Deterrent only: blocks right-click, common DevTools/view-source shortcuts and image dragging.
 * Client-side code can never be fully hidden from a determined visitor.
 * Active in production builds only so `npm run dev` stays usable.
 */
export function protectContent() {
  if (!import.meta.env.PROD) return;

  const block = (e) => e.preventDefault();
  document.addEventListener("contextmenu", block);
  document.addEventListener("dragstart", block);

  document.addEventListener("keydown", (e) => {
    const key = e.key.toLowerCase();
    const ctrl = e.ctrlKey || e.metaKey;
    const devtools =
      e.key === "F12" ||
      (ctrl && e.shiftKey && ["i", "j", "c", "k"].includes(key)) ||
      (e.metaKey && e.altKey && ["i", "j", "c", "u"].includes(key)) ||
      (ctrl && ["u", "s"].includes(key));
    if (devtools) e.preventDefault();
  });
}
